import {roomLabel,roomName} from './places.js';
import {network as N} from './network-data.js';
import {findRoute,navigationSteps,floorName,nearestToilet} from './routing.js';
const app=document.querySelector('#app'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const room=id=>N.rooms.find(r=>r.id===id),map=id=>N.maps.find(m=>m.id===id),label=roomLabel,where=r=>`Budynek ${r.building} · ${floorName(r.floor)}`;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}},save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
const S={screen:'home',start:read('pk-v3-start','entrance'),selected:null,map:'B:0',searchMode:'destination',query:'',filter:'all',points:true,route:null,legs:[],leg:0,stairs:false,voice:false,favorites:read('pk-v4-favorites',['A:1','A:608','A:601']).filter(id=>room(id))};
if(S.start!=='entrance'&&!room(S.start)?.available)S.start='entrance';
function toast(text){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.role='status';t.textContent=text;document.body.append(t);setTimeout(()=>t.remove(),4500);}
function header(title='PK Navigator',back=false){return `<header><div class="row">${back?'<button class="back" data-action="home" aria-label="Wróć do początku">‹</button>':'<span class="logo" aria-hidden="true">➤</span>'}<b class="${back?'title':'brand'}">${title}</b></div><span class="badge">A · B · C</span></header>`;}
function nav(){return `<nav aria-label="Menu główne">${[['home','⌂','Start'],['maps','▤','Plany'],['favorites','☆','Ulubione'],['about','ⓘ','Informacje']].map(([id,icon,title])=>`<button data-action="${id}" class="${S.screen===id?'active':''}"><span aria-hidden="true">${icon}</span>${title}</button>`).join('')}</nav>`;}
function startName(){return S.start==='entrance'?'Wejście główne · B, parter':`Przodem do drzwi ${label(room(S.start))}`;}
function result(r){return `<button class="result" data-room="${esc(r.id)}"><span class="room-icon">${r.building}</span><span><b>${esc(roomName(r))}</b><small>${esc(label(r))} · ${floorName(r.floor)}${r.available?'':' · Brak trasy'}</small></span><span class="end" aria-hidden="true">›</span></button>`;}
function render(){
 if(S.screen==='route'){renderRoute();return;}let body='';
 if(S.screen==='home')body=`${header()}<section class="content"><div class="eyebrow">POLITECHNIKA KOSZALIŃSKA</div><h1>Dokąd idziemy?</h1><p class="muted">Znajdź drzwi sali w budynku A, B lub C.</p><button class="start-button" data-action="search-start"><span aria-hidden="true">◎</span><span><small>Twoje miejsce startowe</small><strong>${esc(startName())}</strong></span><span class="chevron">›</span></button><button class="search-button" data-action="search-destination"><span aria-hidden="true">⌕</span>Wyszukaj salę lub miejsce<span>→</span></button><button class="map-card" style="width:100%" data-action="maps"><img src="${map('B:0').image}" alt="Plan łącznika B"><span class="map-pill">18 planów · A — B — C</span><span class="map-caption"><b>Zobacz plany i punkty trasy</b><span class="map-arrow">→</span></span></button><div class="section-title"><h2>Pod ręką</h2><small>Ulubione miejsca</small></div><div class="favorites">${S.favorites.slice(0,4).map(id=>{const r=room(id);return `<button class="favorite" data-room="${id}"><b>${esc(label(r))}</b><small>${esc(roomName(r))}</small></button>`;}).join('')}</div><p class="note">B łączy A z C na poziomach −1, 0 i 1. Każdy zakręt ma osobną instrukcję. Start przy sali oznacza, że stoisz przodem do jej drzwi.</p></section>`;
 if(S.screen==='search')body=`${header(S.searchMode==='start'?'Skąd ruszasz?':'Znajdź miejsce',true)}<section class="content"><div class="search-mode">${S.searchMode==='start'?'Wybierz miejsce, w którym teraz jesteś':'Wybierz drzwi docelowej sali'}</div><label class="sr-only" for="search">Numer sali, budynek lub nazwa</label><input id="search" class="field" placeholder="Np. 110A, 301C, aula…" value="${esc(S.query)}" autocomplete="off"><div class="building-tabs" role="group" aria-label="Filtr budynków">${['all','A','B','C'].map(b=>`<button data-filter="${b}" class="${S.filter===b?'chosen':''}">${b==='all'?'Wszystkie':b}</button>`).join('')}</div>${S.searchMode==='start'?'<button class="result" data-action="entrance"><span class="room-icon">B</span><span><b>Wejście główne</b><small>Budynek B · Parter</small></span></button>':''}${S.searchMode==='destination'?`<button class="result" data-action="nearest-toilet"><span class="room-icon">WC</span><span><b>Najbliższa toaleta</b><small>Najkrótsza trasa od: ${esc(startName())}</small></span><span class="end">›</span></button>`:''}<p id="result-count" class="search-summary"></p><div id="results" class="results"></div></section>`;
 if(S.screen==='maps')body=`${header('Plany budynków',true)}<section class="content"><div class="select-row"><label>Budynek<select id="building" class="field">${['A','B','C'].map(b=>`<option ${map(S.map).building===b?'selected':''}>${b}</option>`).join('')}</select></label><label>Poziom<select id="floor" class="field">${N.maps.filter(m=>m.building===map(S.map).building).sort((a,b)=>a.floor-b.floor).map(m=>`<option value="${m.id}" ${m.id===S.map?'selected':''}>${floorName(m.floor)}</option>`).join('')}</select></label></div><div class="map-shell" id="map-container"></div><div class="map-tools"><label><input type="checkbox" id="points" ${S.points?'checked':''}> Punkty i połączenia</label><button class="subtle" data-action="search-destination">Szukaj sali</button></div><p class="legend-inline"><span class="dot"></span>droga · <span class="dot gold"></span>drzwi — dotknij punktu</p><div id="place-card">${placeCard()}</div></section>`;
 if(S.screen==='favorites')body=`${header('Ulubione miejsca',true)}<section class="content"><div class="results">${S.favorites.map(id=>result(room(id))).join('')||'<p class="empty">Zaznacz gwiazdkę przy wybranej sali.</p>'}</div></section>`;
 if(S.screen==='about')body=`${header('O prototypie',true)}<section class="content"><h1>Do drzwi sali.</h1><p class="muted">18 poprawionych planów. Trzy budynki. Przejścia przez łącznik B.</p><div class="about-box"><h2>Jak korzystać</h2><p class="muted">Wybierz miejsce startowe i cel. Niebieska linia prowadzi po punktach korytarza, a złoty punkt wskazuje drzwi. Każdy zakręt potwierdzasz przyciskiem. Jeśli wybierasz salę jako start, stań przodem do jej drzwi. Prototyp nie ustala pozycji automatycznie.</p></div><div class="about-box"><h2>Plany i przejścia</h2><p class="muted">Trasy opierają się na ręcznie naniesionych punktach z planów V3. Przejścia między budynkami są na poziomach −1, 0 i 1. Zmianę piętra pokazujemy jako osobny etap.</p></div><div class="about-box"><h2>Brakujące wejścia</h2><p class="muted">Dla ${N.rooms.filter(r=>!r.available).map(r=>esc(label(r))).join(', ')} nie ma potwierdzonego wejścia na rysunku. Te miejsca można znaleźć, ale nie wyznaczamy do nich trasy.</p><p class="warning">Na II piętrze C plan powtarza numer 201. Pokój biurowy pokazujemy jako „202 (na planie: 201)” zgodnie z wcześniejszym planem.</p></div><button class="secondary" data-action="export">Pobierz punkty i połączenia</button></section>`;
 app.innerHTML=body+nav();window.scrollTo(0,0);bind();if(S.screen==='search')updateResults();if(S.screen==='maps')drawMap(S.map);
}
function placeCard(){const r=room(S.selected);if(!r||r.map!==S.map)return '<p class="muted">Wybierz złoty punkt przy drzwiach albo wyszukaj salę.</p>';return `<article class="place-card"><div class="place-title-row"><span class="eyebrow">${where(r)}</span><button class="star" data-action="star" aria-label="${S.favorites.includes(r.id)?'Usuń z':'Dodaj do'} ulubionych">${S.favorites.includes(r.id)?'★':'☆'}</button></div><h2>${esc(roomName(r))}</h2><p class="muted">${esc(label(r))} · cel przy drzwiach</p>${r.note?`<p class="warning">${esc(r.note)}</p>`:''}${!r.available?`<p class="warning">${esc(r.reason)} Nie wyznaczamy trasy przez ścianę.</p>`:''}<div class="button-row"><button class="secondary" data-action="set-start" ${r.available?'':'disabled'}>Jestem tutaj</button><button class="primary" data-action="navigate" ${r.available?'':'disabled'}>Prowadź tutaj →</button></div><div class="route-options"><label><input type="checkbox" id="stairs" ${S.stairs?'checked':''}> Preferuję schody</label></div><p class="status-line">Start: ${esc(startName())}</p></article>`;}
function updateResults(){const q=S.query.toLocaleLowerCase('pl').trim().replace(/[·,:-]/g,' '),parts=q.split(/\s+/).filter(Boolean);const rs=N.rooms.filter(r=>(S.filter==='all'||r.building===S.filter)&&parts.every(p=>`${r.building} ${r.number} ${roomLabel(r)} ${roomName(r)}`.toLocaleLowerCase('pl').includes(p))).sort((a,b)=>a.building.localeCompare(b.building)||a.floor-b.floor||a.number.localeCompare(b.number,'pl',{numeric:true}));document.querySelector('#result-count').textContent=`Liczba miejsc: ${rs.length}${rs.length>60?' · wpisz numer, aby zawęzić wyniki':''}`;document.querySelector('#results').innerHTML=rs.slice(0,60).map(result).join('')||'<p class="empty">Nie znaleziono miejsca. Spróbuj wpisać sam numer sali.</p>';}
function choose(id){const r=room(id);if(!r)return;if(S.screen==='search'&&S.searchMode==='start'){if(!r.available){toast(r.reason);return;}S.start=id;save('pk-v3-start',id);S.screen='home';render();toast(`Start: przy drzwiach ${label(r)}`);return;}S.selected=id;S.map=r.map;S.screen='maps';render();}
function bind(){app.onclick=e=>{const t=e.target.closest('[data-action],[data-room],[data-filter]');if(!t)return;if(t.dataset.room){choose(t.dataset.room);return;}if(t.dataset.filter){S.filter=t.dataset.filter;render();return;}action(t.dataset.action);};
 document.querySelector('#search')?.addEventListener('input',e=>{S.query=e.target.value;updateResults();});document.querySelector('#building')?.addEventListener('change',e=>{S.map=`${e.target.value}:0`;S.selected=null;render();});document.querySelector('#floor')?.addEventListener('change',e=>{S.map=e.target.value;S.selected=null;render();});document.querySelector('#points')?.addEventListener('change',e=>{S.points=e.target.checked;if(S.screen==='route')drawMap(S.legs[S.leg].map,S.legs[S.leg]);else drawMap(S.map);});document.querySelector('#stairs')?.addEventListener('change',e=>S.stairs=e.target.checked);
}
function action(a){if(['home','maps','favorites','about'].includes(a)){S.screen=a;render();return;}if(a?.startsWith('search-')){S.screen='search';S.searchMode=a==='search-start'?'start':'destination';S.query='';S.filter='all';render();document.querySelector('#search').focus();return;}if(a==='entrance'){S.start='entrance';save('pk-v3-start',S.start);S.screen='home';render();return;}
 if(a==='set-start'){const r=room(S.selected);if(!r?.available)return;S.start=r.id;save('pk-v3-start',r.id);render();toast('Miejsce startowe zapisane.');}if(a==='star'){const i=S.favorites.indexOf(S.selected);if(i<0)S.favorites.push(S.selected);else S.favorites.splice(i,1);save('pk-v4-favorites',S.favorites);render();}
 if(a==='nearest-toilet'){const found=nearestToilet(S.start==='entrance'?N.entrance:room(S.start).node,{preferStairs:S.stairs});if(!found){toast('Brak dostępnej trasy do toalety.');return;}S.selected=found.room.id;S.map=found.room.map;navigate();return;}if(a==='navigate')navigate();if(a==='next'){if(S.leg<S.legs.length-1){S.leg++;renderRoute();speak();}else{S.start=S.selected;save('pk-v3-start',S.start);S.screen='maps';S.map=room(S.selected).map;render();toast('Jesteś przy drzwiach celu.');}}if(a==='previous'&&S.leg>0){S.leg--;renderRoute();}if(a==='voice'){S.voice=!S.voice;renderRoute();if(S.voice)speak();else window.speechSynthesis?.cancel();}if(a==='exit-route'){S.screen='maps';S.map=room(S.selected).map;window.speechSynthesis?.cancel();render();}
 if(a==='export'){const blob=new Blob([JSON.stringify(N,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='PK-punkty-A-B-C.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
function navigate(){const r=room(S.selected);if(!r?.available)return;S.route=findRoute(S.start==='entrance'?N.entrance:room(S.start).node,r.node,{preferStairs:S.stairs});if(!S.route){toast('Brak połączonej trasy do tych drzwi. Wybierz inne miejsce startowe.');return;}S.legs=navigationSteps(S.route,{startRoom:S.start==='entrance'?null:room(S.start),destination:r});S.leg=0;S.screen='route';renderRoute();speak();}
function legText(){return S.legs[S.leg];}
function renderRoute(){const l=S.legs[S.leg],m=map(l.map),t=legText();app.innerHTML=`<section class="navigation"><div class="map-half"><div id="map-container" style="position:absolute;inset:0"></div><div class="map-toolbar"><button class="back" data-action="exit-route" aria-label="Zakończ prowadzenie">×</button><span class="map-label">Budynek ${m.building} · ${floorName(m.floor)}</span></div><div class="map-legend">Niebieska linia: trasa · złoty punkt: koniec kroku</div></div><div class="instruction-half"><div class="route-top"><b>Do drzwi ${esc(label(room(S.selected)))}</b><span>Krok ${S.leg+1} z ${S.legs.length}</span></div><div class="progress"><span style="width:${(S.leg+1)/S.legs.length*100}%"></span></div><div class="instruction-copy"><h2><span class="inline-direction" aria-hidden="true">${t.icon}</span> ${esc(t.title)}</h2><p>${esc(t.body)}</p><details class="all-instructions"><summary>Cała instrukcja · ${S.legs.length}</summary><ol>${S.legs.map((step,i)=>`<li class="${i===S.leg?'current':''}"><b>${esc(step.title)}</b><span>${esc(step.body)}</span></li>`).join('')}</ol></details></div><div class="map-tools"><label><input id="points" type="checkbox" ${S.points?'checked':''}> Pokaż punkty</label><button class="small-button" data-action="voice" aria-pressed="${S.voice}">${S.voice?'Głos: włączony':'Głos: wyłączony'}</button></div><div class="button-row">${S.leg>0?'<button class="secondary" data-action="previous" aria-label="Poprzedni krok">←</button>':''}<button class="primary" data-action="next">${esc(t.button)}</button></div></div></section>`;window.scrollTo(0,0);bind();drawMap(l.map,l);}
function speak(){if(!S.voice||!window.speechSynthesis)return;window.speechSynthesis.cancel();const t=legText(),u=new SpeechSynthesisUtterance(t.body);u.lang='pl-PL';window.speechSynthesis.speak(u);}
function drawMap(mapId,leg=null){const container=document.querySelector('#map-container');if(!container)return;const m=map(mapId),ns=Object.values(N.nodes).filter(n=>n.map===mapId),rs=N.rooms.filter(r=>r.map===mapId),walk=N.edges.filter(e=>e.kind==='walk'&&N.nodes[e.a].map===mapId);let overlay='';
 if(S.points)overlay=`<g stroke="#2083c5" stroke-width="2.5" opacity=".55">${walk.map(e=>{const a=N.nodes[e.a],b=N.nodes[e.b];return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}"/>`;}).join('')}</g><g fill="#2083c5" stroke="white" stroke-width="1.5">${ns.map(n=>`<circle cx="${n.x}" cy="${n.y}" r="4"/>`).join('')}</g>`;
 if(leg){const pts=leg.nodes.map(n=>`${n.x},${n.y}`).join(' '),context=leg.contextNodes.map(n=>`${n.x},${n.y}`).join(' '),a=leg.nodes[0],b=leg.nodes.at(-1);overlay+=`<polyline points="${context}" fill="none" stroke="#2083c5" stroke-opacity=".25" stroke-width="5" vector-effect="non-scaling-stroke" stroke-linejoin="round"/><polyline points="${pts}" fill="none" stroke="white" stroke-width="14" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/><polyline class="active-route" points="${pts}" fill="none" stroke="#2083c5" stroke-width="9" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${a.x}" cy="${a.y}" r="19" fill="#1d1a53" stroke="white" stroke-width="3" vector-effect="non-scaling-stroke"/><circle cx="${b.x}" cy="${b.y}" r="21" fill="#d9b057" stroke="#1d1a53" stroke-width="3" vector-effect="non-scaling-stroke"/>`;if(leg.startHeading!=null)overlay+=`<path d="M 26 0 L -11 -13 L -5 0 L -11 13 Z" transform="translate(${a.x} ${a.y}) rotate(${leg.startHeading})" fill="#1d1a53" stroke="white" stroke-width="2" vector-effect="non-scaling-stroke"/>`;}

 else overlay+=rs.map(r=>`<g class="map-room" tabindex="0" role="button" aria-label="${esc(label(r)+' '+roomName(r))}" data-map-room="${esc(r.id)}"><circle cx="${r.x}" cy="${r.y}" r="16" fill="transparent"/><circle cx="${r.x}" cy="${r.y}" r="${r.id===S.selected?12:7}" fill="${r.available?'#d9b057':'#9aa2b5'}" stroke="${r.id===S.selected?'#1d1a53':'white'}" stroke-width="${r.id===S.selected?4:2}"/><title>${esc(label(r))}</title></g>`).join('');
 container.innerHTML=`<svg viewBox="0 0 1888 1334" aria-label="Plan: budynek ${m.building}, ${floorName(m.floor)}"><image href="${m.image}" width="1888" height="1334"/>${overlay}</svg><div class="zoom"><button data-zoom="in" aria-label="Powiększ mapę">+</button><button data-zoom="out" aria-label="Pomniejsz mapę">−</button><button data-zoom="reset" aria-label="Cały plan">⊡</button></div>`;
 const svg=container.querySelector('svg');let vb=[0,0,1888,1334];if(leg){const xs=leg.nodes.map(n=>n.x),ys=leg.nodes.map(n=>n.y),x=Math.min(...xs)-170,y=Math.min(...ys)-170,w=Math.max(550,Math.max(...xs)-x+170),h=Math.max(550,Math.max(...ys)-y+170);vb=[x,y,w,h];}else if(S.selected&&room(S.selected)?.map===mapId){const r=room(S.selected);vb=[r.x-430,r.y-310,860,620];}const set=()=>svg.setAttribute('viewBox',vb.join(' '));set();
 function zoom(f){const w=Math.max(160,Math.min(3776,vb[2]*f)),h=vb[3]*w/vb[2];vb=[vb[0]+(vb[2]-w)/2,vb[1]+(vb[3]-h)/2,w,h];set();}
 container.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){vb=[0,0,1888,1334];set();}else zoom(b.dataset.zoom==='in'?.7:1.4);});svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.15:1/1.15);},{passive:false});const pointers=new Map();let origin,dragged=false;
 const coord=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());};
 svg.onpointerdown=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});origin={x:e.clientX,y:e.clientY};dragged=false;svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);if(pointers.size===2){const other=[...pointers.entries()].find(([id])=>id!==e.pointerId)[1],d=Math.hypot(old.x-other.x,old.y-other.y),d2=Math.hypot(e.clientX-other.x,e.clientY-other.y);if(d2>10)zoom(d/d2);dragged=true;}else{const dx=e.clientX-old.x,dy=e.clientY-old.y,scale=svg.getScreenCTM().a;vb[0]-=dx/scale;vb[1]-=dy/scale;set();if(Math.hypot(e.clientX-origin.x,e.clientY-origin.y)>5)dragged=true;}pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});};
 svg.onpointerup=e=>{pointers.delete(e.pointerId);if(!dragged&&!leg){const p=coord(e),r=rs.map(r=>[r,Math.hypot(r.x-p.x,r.y-p.y)]).sort((a,b)=>a[1]-b[1])[0];if(r&&r[1]<Math.max(18,24/svg.getScreenCTM().a))choose(r[0].id);}};svg.onpointercancel=e=>pointers.delete(e.pointerId);svg.querySelectorAll('[data-map-room]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.mapRoom);}});
}
window.PKNavigator={setCurrentLocation(id){if(id==='entrance'||room(id)?.available){S.start=id;save('pk-v3-start',id);render();return true;}return false;}};render();

